// ---- Help / How to use: grouped into topics, searchable, with a jump bar. GM-only topics only show for the GM.
const HELP_S=()=>{
 const S=[];const add=(id,ico,title,intro,items,o)=>S.push({id,ico,title,intro,items,...(o||{})});
 add('start','🚀','Start here','Everything on this site is shared and in-world. Read the basics once and the rest explains itself.',[
 '<b>What this is:</b> a shared message system for our Shadowrun game. Post as your character, read what other characters say, and pick up hints the GM drops between sessions. Everyone can read everything, including Private Channels: "private" is an in-world label, not a real lock.',
 '<b>Signing in:</b> you sign in with your email address. If you cannot get in, ask the GM to add your email to the allow list.',
 '<b>Set up your Profile first:</b> ⚙ Menu, Profile. Choose your handle (your character name), handle color, an optional affiliation tag (a corp or gang) and an optional signature. These become the defaults on your posts. Add your Discord user ID there so the Discord channel can ping you. Persona style (your role) adds an icon and colored edge to your new posts.',
 '<b>Make it look the way you like:</b> ⚙ Menu, Display (theme, accent color, text size, high contrast, effects and more) and ✨ Flair (badge, title tag, name effect, portrait frame). Both only change what you see or how you appear. See "Display, alerts and accessibility".',
 '<b>The top bar:</b> your handle, who is online, the real time and the in-game Net Time, the 🔔 bell (mentions and replies), 🎲 Rolls (every table roll), the ⚙ Menu and Sign out (⏻). The scrolling banner under it shows the newest posts and street news. The 📍 scene chip shows where the GM says the party is, and a Seattle weather chip sits by the ticker.',
 '<b>Home:</b> the first link in the left menu opens your own home page, and it is the page you land on when you arrive (turn that off in ⚙ Menu, Display). It shows your sheet at a glance (wounds, Toughness, bennies you can change with − and +, Heat and Rep), anything the GM has asked you to do (tick it off when done), what needs your attention, your jobs and favors, unread threads, your last rolls, where you stand with each faction, upcoming calendar events and the newest clue board notes. If you have more than one character, pick which one it shows. On a wide screen, drag the grip on the right edge of the page to make Home wider so more cards sit side by side; double-click the grip to put it back.',
 '<b>What\'s new:</b> a short notice appears after each update with just the new things as bullets; older updates are one click away. The button at the top of this page shows it again.'
 ]);
 add('around','🧭','Finding your way around','The menu on the left (☰ Menu on a phone) groups everything. Tap a board and you are in it.',[
 '<b>Messages:</b> Inbox (mentions and replies to you), Unread, ★ Saved and Trash. <b>Private Channels</b> are direct messages from one handle to another, or a group chat with several. In the To box, pick a handle (or type one) and press Enter or Add; keep adding more for a group, and click a name to take it off. Everyone in the group sees the conversation in their Inbox, and Only mine shows the ones that involve you. Edit title also lets you change who is in it.',
 '<b>Public Grid:</b> general, shadowtalk, runs wanted, black market, leaks and rumors, and anonymous drops. <b>+ New Public Grid channel</b> at the end of the list adds one. <b>Faction Channels</b> (corps, gangs, syndicates) work the same way with <b>+ New faction channel</b>. Only the GM can delete a channel.',
 '<b>World Building:</b> Off Screen Scenes, Networking Contacts, Seattle Map, Seattle Districts and Rules &amp; Slang.',
 '<b>Party Management:</b> Plot Hooks and Missions, Downtime Activities, Finds and Funds, and the Job Board. <b>Newsfeed:</b> the Newspaper and Matrix News.',
 '<b>Table:</b> Tabletop, Initiative, Dice Roller, Range &amp; Cover and Table Stats. <b>Character:</b> Character Sheets, Gear &amp; Shopping, My Notes, Character Directory and NPC Handles. <b>Campaign:</b> Calendar, Timeline, Handout Vault, GM Dossiers and Heat &amp; Rep. <b>Help &amp; More:</b> Custom Emoji, this Help page and Feedback &amp; Suggestions. The GM also has a <b>GM Hub</b> of their own.',
 '<b>Sort the menu your way:</b> click a heading in the left menu to fold or unfold that group (it is remembered on every device you use). Point at any page and press its <b>☆</b> to pin it to a <b>Pinned</b> group at the top (up to 8); press the ★ again to unpin. A group that holds the page you are on always stays open.',
 '<b>Quick switcher:</b> press <b>Ctrl+K</b> (or <b>/</b>, or tap 🔍 on a phone) and start typing to jump straight to any page, character, NPC, token on the map, clue note, map note, handout, district or rule. Use the arrow keys and Enter. The last row searches everything for what you typed.',
 '<b>Shortcuts and page help:</b> press <b>?</b> to see the keyboard shortcuts. The <b>?</b> button in the top bar (⚙ Settings on a phone) opens just the help for the page you are on.',
 '<b>My Characters:</b> tick <b>add to side bar</b> on any sheet and it appears at the top of the menu for one-click access.',
 '<b>Search:</b> the search box in the top bar searches everything in one go: posts, jobs, missions and other cards, character sheets (name, concept, edges, skills, weapons and notes), people and contacts, districts and map pins, factions, rules and slang, handouts, newspaper and Matrix News, gear, clue board notes, Tabletop map notes and maps. Results are grouped, with chips along the top (Posts, Sheets, Places and so on) that show how many matched and let you look at one kind at a time. Words are matched anywhere, best matches come first and your words are highlighted. Put <b>"quotes"</b> around an exact phrase, a <b>-minus</b> in front of a word to leave it out, <b>by:Name</b> for posts by one person, <b>in:board</b> for one board, or <b>type:sheets</b> (jobs, places, rules, news, gear, clues, tabletop) to look at one kind. The board, person and in-game date filters work on posts. Hidden character sheets and GM secrets are never searched.',
 '<b>Pages:</b> long threads and lists are split into pages. Use Prev/Next or the page numbers and choose how many to show (10, 25, 100 or All). Your choice is remembered. Floating <b>Top</b> and <b>Latest</b> buttons jump to either end of a long thread.',
 '<b>Who is online:</b> the top bar shows how many people have the site open, with their handles in the menu.',
 '<b>On a phone:</b> the top bar is one row: ☰ Menu opens the page list (with your Profile, Display and other settings in a folded Settings group at the top), 🔍 is the quick switcher, 🔔 is the bell and 🎲 the roll history. Busy toolbars on the Clue Board fold into a <b>More</b> button. On the Tabletop, press and hold a token for its menu. The quick-roll bar scrolls sideways.'
 ]);
 add('reading','📖','Reading and keeping up','How to tell what is new, and how to read in the order you want.',[
 '<b>Unread tracking:</b> a pink NEW tag with a number shows how many posts in a thread you have not read, and new posts are marked inside the thread. Numbers beside board names count threads with unread posts. The <b>Unread</b> page lists everything new, with Mark all read, and <b>Mark unread</b> inside a thread flags it again. Read status is private to you and follows you across devices.',
 '<b>New cards:</b> pages made of cards (Job Board, Plot Hooks and Missions, Downtime, Finds and Funds, Networking Contacts, Seattle Map, Seattle Districts, Rules &amp; Slang, Newspaper and Matrix News) also show a number in the menu when someone else adds or changes a card. They are listed on the Unread page under New or changed cards. Opening the page clears the number and shows a 🆕 line at the top naming what was new. Your own changes never count, and Mute hides the number.',
 '<b>Since you were last here:</b> a banner summarizes what is new when you come back.',
 '<b>Mention alerts:</b> the 🔔 in the top bar counts unread mentions and private replies. Click it to read them, jump to the thread or mark all read. A pop-up also appears when a new one arrives (turn that off in Display).',
 '<b>Inbox:</b> collects posts that mention you, plus replies in private channels you are part of. Opening a message marks it read and replying marks it replied. Handled messages turn grey.',
 '<b>Mute a board:</b> the 🔔 Mute button at the top of a board hides its unread numbers and chimes. @mentions still reach you. Unmute from the same button or from Display.',
 '<b>Saved posts:</b> press ☆ Save on any post or handout to keep it in ★ Saved. Only you see it, and it follows you to other devices.',
 '<b>Real time and in-game time:</b> every post shows the in-game time and, in small text under it, 🕒 when it was really posted. Threads and the Timeline are sorted by game time, but <b>Sort by: game time / real time</b> switches them to real-world order. Your choice is remembered.',
 '<b>Order:</b> inside a thread, posts are shown newest first by default. The <b>Order</b> button flips the whole thread to oldest first.',
 '<b>Lists of threads:</b> they are ordered by in-game time, oldest first, so 1/3/2022 comes before 1/5/2022. The Sort button can switch to newest posted or latest activity. Times like 2077-03-14 23:42, 3/14/2077, 14MAR2077 and Mar 14, 2077 are understood. Times that cannot be read as dates sort after dated ones.',
 '<b>Filters and tags:</b> the Filters panel on a thread list narrows threads by tag, handle or in-game date range. Tags can be added when you start a dossier or private message.',
 '<b>Timeline:</b> Campaign, Timeline lists every post from every board in in-game order, together with Clue Board notes that have an in-game date and Calendar events. Tick or untick Posts, Clue Board notes and Calendar events to choose what shows. Click a clue note or event to open it.',
 '<b>Scrolling banner:</b> the five most recent posts (private ones in pink), the newest few new or changed cards from the past week (in amber: jobs, contacts, map pins and so on; click one to open that page; muted pages are left out), then the GM\'s headlines and a rotating mix of Seattle street news. Click a post in it to open it.',
 '<b>Hover cards:</b> on a computer, point at a handle or an @mention to see a small card with their picture, role, affiliation, post count and a bit of their bio, plus buttons for their directory page and character sheet. On a phone, tapping a handle opens the directory page.'
 ]);
 add('posting','✍️','Posting','Writing a post, formatting it, and fixing mistakes.',[
 '<b>New post:</b> click <b>New post</b>, write your message and click <b>Transmit</b>. Ctrl+Enter also sends. Unsent posts are saved as a draft in your browser and come back if you close the page (<b>Discard it</b> clears a restored draft).',
 '<b>In-game time:</b> separate from real time. The time box fills in as a random 2 to 17 minutes after the latest time in that thread, and you can change it. The <b>Net Time</b> in the top bar is a shared clock that only moves when someone posts: every new post moves it forward by a random 3 to 15 minutes, and it never moves with real time. Anyone can set it with <b>Set clock</b> (until it has been set once it shows a dash and posting does not move it). Editing a post does not move it.',
 '<b>Posting as:</b> your handle by default, but it can be any handle. <b>NPC handles</b> (Game Management, NPC Handles) are shared: anyone can add, update or remove them and post as them on any board, and those posts carry an NPC badge. Each NPC can have a description that shows on the NPC list and its character page. <b>UNKNOWN USER</b> posts anonymously. In Off Screen Scenes use the Writing as box instead (see "Off Screen Scenes").',
 '<b>Mentions:</b> type <b>@</b> and pick a handle. Their name is highlighted for everyone and the post lands in their Inbox.',
 '<b>Quote:</b> the Quote button copies a post into your reply and @mentions the person. Click ✕ Remove the quote if you only want the mention. A quoted post shows "↩ quoted Name", and clicking it jumps to the original. Private channels have no Quote button.',
 '<b>Reactions:</b> every post has Vouch, Burn and Heard buttons. Click to add yours, click again to remove it, hover to see who reacted. The ☺+ button reacts with any emote, including custom ones.',
 '<b>Images:</b> click <b>Attach image</b> to add maps, photos or wanted posters, or press <b>Ctrl+V</b> to paste a copied picture, or drag a picture file onto the page while a picture field is open. Click an image in a post to enlarge it. The ✕ next to a thumbnail removes it before you send.',
 '<b>Links and previews:</b> web addresses you paste become clickable. Under the post you get a preview: pictures show inline, YouTube and Vimeo videos are click-to-play (nothing loads from them until you click), links to other posts here show a card, and other links show the page title and description. At most 3 previews per post. Turn previews off in Display.',
 '<b>Emoji:</b> 15 Shadowrun-style emoji are built in: :preem: :drek: :haha: :sad: :slotted: :mirrorshades: :hmm: :cyberheart: :cybereyes: :burn: :flatlined: :nuyen: :d6: :ice: :drone:. Type a name between colons or use the 😀 Emoji button. Add your own under Game Management, Custom Emoji.',
 '<b>Dice in a post:</b> type <b>/roll 6d6</b> and it becomes a recorded roll. With d6 pools it counts hits (5s and 6s). Modifiers work, like /roll 2d6+3. (The Dice Roller and character sheets use Savage Worlds rules instead; see "Dice and combat".)',
 '<b>Edit and delete:</b> every post has Edit and Delete buttons. Anyone can use them because we build the world together, so please only change your own posts unless the GM asks. Edited posts show an (edited) link that opens earlier versions. Deleted posts go to the <b>Trash</b>, where anyone can restore them. Deleted cards (jobs, contacts, missions, downtime, ledger lines, events, handouts and map pins) go there too. Only the GM can delete from the Trash for good.',
 '<b>Undo:</b> after you delete something, an Undo bar appears for about 10 seconds.',
 '<b>Pin a post:</b> every post has a Pin button. Pinned posts stay at the top of the thread on every page.',
 '<b>Link to a post:</b> the Link button copies a direct link, and Discord notifications include one. Opening a link jumps straight to that post.',
 '<b>Editing a private conversation:</b> use Edit title at the top to change the subject (or the recipient), and Delete conversation to move the whole thread to the Trash.',
 '<b>Rules and slang:</b> World Building, Rules &amp; Slang lists rules, street slang and setting terms. Known words are underlined in posts, and tapping one shows what it means. Anyone can add or change terms. Switch the underlines off in Display.'
 ]);
 add('format','🅱️','Formatting your message','The message box works like a word processor: select text, then click a button above the box. What you see is what gets posted. Click the same button again to remove the style.',[
 '<b>B</b> bold (Ctrl+B), <b>I</b> italic (Ctrl+I), <b>U</b> underline (Ctrl+U), <b>S</b> strikethrough (good for a rumor that turned out false).',
 '<b>H</b> turns the line into a heading. <b>• List</b> and <b>1. List</b> make lists: Enter for the next item, Enter twice to finish. <b>―</b> is a divider line. <b>&lt;/&gt;</b> is code style, for comm codes and serial numbers. <b>❝ Quote</b> turns a paragraph into a quote.',
 '<b>█ Redact</b> hides selected text behind a black bar. Readers click the bar to reveal it, which is good for secrets and hints. A link inside redacted text cannot be clicked until it is revealed.',
 '<b>@ Mention</b> tags a player (typing @ does the same). <b>😀 Emoji</b> opens the emoji picker. <b>↶ ↷</b> undo and redo.'
 ]);
 add('scenes','🎬','Off Screen Scenes','Scenes your character plays out away from the table: downtime, solo scenes, flashbacks and anything between runs.',[
 '<b>Chat room style:</b> <b>New scene</b> starts one, then everyone talks in it like a Discord channel. Type and press Enter to send (Shift+Enter for a new line). <b>Rich editor</b> gives you formatting and images. There is no in-game time on scene messages, just the real time.',
 '<b>Player and Writing as:</b> under the message box, <b>Player</b> is you (your handle, so the table always knows who is typing) and <b>Writing as</b> is the character you are speaking as in this scene. Type a name, or press a button for your own characters, NPCs or characters already in the scene. Leave it empty to post as yourself. <b>✕ just me</b> clears it.',
 '<b>How it looks:</b> each message shows the character with the player behind it, like "Mr. Johnson 👤 Cat". Posting as an NPC name also gives the NPC badge and color. The box remembers your choice for each scene, and the Rich editor has the same field.',
 '<b>Change it later:</b> Edit on a message lets you change which character it was written as.',
 '<b>Scene tools:</b> Edit title, Delete scene (to the Trash) and Mark unread are at the top of the scene.'
 ]);
 add('people','🧑‍🤝‍🧑','Characters, NPCs and contacts','Who is who in the world.',[
 '<b>Profiles:</b> click any handle, in a post or in the Character Directory, to open that character\'s page. Create profile or Edit profile is optional and anyone can fill one in: role, species, affiliation, appearance, background, quirks and a portrait. Every thread that handle posted in is listed there too.',
 '<b>Portraits and the directory:</b> every character with a sheet is listed in the Character Directory and shows the sheet\'s portrait (a character without a sheet uses the portrait from their directory profile). Click the portrait on a sheet to open that character\'s directory page, and use Open character sheet there to go back.',
 '<b>Flair:</b> ⚙ Menu, Flair. Pick a badge, a short title, a name effect and a portrait frame that others see next to your handle, plus a dice theme and roll animation that only you see. You can hide other people\'s flair there too.',
 '<b>NPC Handles:</b> a shared list of NPC names anyone can post as. Use Edit next to an NPC to change its name, color, tag, signature or description. The 🎲 Random button makes NPC names.',
 '<b>Networking Contacts:</b> contact cards with whose contact they are, role, location, affiliation, Loyalty (1 to 6), Connection (1 to 12), how to reach them, services, trust and pictures. Filter by owner or trust. If the name matches an NPC handle the contact gets an NPC ↗ badge that opens that character\'s page, which lists everyone who has them as a contact and any jobs they have offered. Adding a contact with a new name offers to create the NPC handle too.',
 '<b>GM Dossiers:</b> pinned reference posts for NPCs, locations, corporations and more. Open Game Management, GM Dossiers, click New dossier, and choose a category. All dossiers are listed there by category.',
 '<b>Heat and Rep:</b> Game Management, Heat and Rep shows each runner\'s Heat (0 to 10) and Street Rep, and how factions feel about the team (−10 to +10). Everyone can look. The GM changes them, and a history keeps who, when and why. Factions have profiles (type, tagline, what the players know, what they want, holdings and key people); open the profile line under a faction to read it. Under each faction you also see where <b>you</b> stand (the party standing plus any personal change the GM has made for you), what that means for social rolls with them (Hostile −2, Cold −1, Warm +1, Friendly +2, Allied +3 as a suggestion), and a list of each runner\'s standing.'
 ]);
 add('sheets','🧾','Character sheets','Tools, Character Sheets holds a Savage Worlds sheet for every character.',[
 '<b>Creating a sheet:</b> click <b>+ New character</b> and fill in the character name and the handle. The handle is the name they use on the board, and funds and equipment follow the handle. The field under Handle is the <b>F.SIN</b> (the name on the fake SIN card). <b>Import from Savaged.us</b> builds or updates a sheet from an exported JSON file; a preview shows what will be created or changed, and gear goes into Funds and Equipment.',
 '<b>What is on it:</b> attributes and skills (each with a die and a +/− bonus), Parry and Toughness worked out for you, wounds and fatigue, Power Points, Advances, Edges, Hindrances, weapons, powers, notes and portrait. Roll next to any attribute or skill rolls a trait die and Wild Die with its bonus and your wound and fatigue penalties. A blank skill rolls unskilled (d4−2). Weapons have Attack and Damage buttons (damage understands things like 2d6+1 and Str+d8). Clear log empties the roll results shown at the top of the sheet.',
 '<b>Who can edit:</b> anyone can look at and edit any sheet, so please only change someone else\'s with their say-so. Tick <b>hide character sheet</b> at the top of your own sheet to hide it from the other players (the GM still sees it). Only the player who created a sheet, or the GM, can delete it.',
 '<b>Edges and hindrances:</b> + Add edge and + Add hindrance open the full list. Tap one to read it. Edges you cannot take yet show what is missing. Bonuses that are always on (Alertness, Block, Fleet-Footed, Luck and so on) change Parry, Toughness, Pace, bennies, Power Points and skill rolls for you, and the roll shows them in brackets. Bonuses that only apply sometimes are tick boxes in the Situational row above the roll box: tick what applies, then roll.',
 '<b>Edge library:</b> Character Sheets, Edge library is one shared list anyone can edit: change an edge or hindrance, hide the ones your setting does not use, or add your own with their own requirements and effects. The last editor\'s name is shown.',
 '<b>Advances:</b> type your XP on the sheet (every 5 is an advance), then + Take an advance. Choose a new edge, raise a skill or two, learn a new skill, raise an attribute (once per rank) or ease a hindrance. The sheet applies it and adds it to the list. Undo last takes the most recent one back. Rank follows the number of advances (4 per rank).',
 '<b>Favorite rolls:</b> FAVORITE ROLLS keeps your most-used rolls. + Add favorite roll lets you pick an attribute, a skill or a plain die, add a bonus and a note. Click a favorite to roll it. ✎ edits it and ✕ deletes it.',
 '<b>Pin a character (quick-roll bar):</b> tick 📌 pin to top bar on a sheet. A bar under the ticker then shows its wounds, Toughness, bennies (− and + buttons), conditions and your favorite rolls on every page, plus quick d4 to d20 dice and a ± box for a one-time bonus or penalty on the next roll. <b>⚡ More</b> opens a picker to roll any attribute or skill and star the ones you want on the bar.',
 '<b>Play mode:</b> the Play mode button hides the long form and shows only what you use during a game: tap a die to roll an attribute or skill, your weapons with attack and reload, powers with cast, timers and drones. Edit mode brings the whole sheet back.',
 '<b>Layout:</b> the Layout button moves sections up or down and folds the ones you rarely use. You can also click a section title to fold it. It is saved for you only, and Reset puts the default order back.',
 '<b>History and printing:</b> the History button shows who changed what and lets you undo a change. Print / PDF makes a clean black and white copy you can print or save as a PDF.',
 '<b>Duplicate:</b> makes a separate copy of a sheet (and its gear if you like). The GM can tick Make the copy an NPC, or use Make NPC on a sheet to take it over.',
 '<b>Strain:</b> a character with cyberware gets a Cyberware and Strain panel with the total against Vigor and Spirit, a list of implants and an adjustment box for bioware or house rules.',
 '<b>Timers:</b> the Timers box counts powers and conditions down while combat is running. Casting a power with a duration in rounds starts one for you. Add your own with + Timer, and give it a roll penalty if it is a sustained power. At zero it shows Ended until you dismiss it.'
 ]);
 add('gear','🛒','Gear, money and armor','Buying, carrying and wearing things.',[
 '<b>Gear &amp; Shopping:</b> Tools, Gear &amp; Shopping holds about 500 items from the Gear and Magic and Machine catalogs. Search or filter by category, then Buy for a character. Pick the quantity, adjust the price if you haggled, and choose whether to take it from their funds (this logs a spending line in Finds and Funds). Cyberware shows all four grades side by side (Gutterware, Streetware, Customware, Milware), each with its own Strain and price. Cyberdecks can be bought New or Refurbished (half price). The Inventory tab shows each character\'s items, their worth, funds and cyberware Strain. Magic entries are reference only.',
 '<b>Custom gear:</b> ＋ Add custom item adds your own weapon, armor, cyberware or other gear to the catalog. Everyone can see and buy it. Only the person who added it, or the GM, can edit or remove it.',
 '<b>Funds and Equipment on a sheet:</b> funds are the same as in Finds and Funds, so spending on the sheet changes what the shop sees. Equipment is the shop inventory plus items you add by hand, each with its quantity (type a number or use − and +) and weight. <b>Sell</b> sells some or all of an item: the suggested price is half of what you paid, you can change it, and the money can go to the character\'s funds and be logged. Click or hover an item\'s name to read its description, grade and Strain.',
 '<b>Gear that changes your numbers:</b> items with effects have an Installed or In use switch. When it is on, the bonus shows in the green EDGE box beside the skill and in your rolls. Open any item to see or change its Effects, or to give a custom item its own. Wired Reflexes, Wetware and skillsofts raise the die itself. If you already added an implant\'s bonus by hand, untick Installed so it is not counted twice.',
 '<b>Wearing armor:</b> tick <b>Wear</b> next to armor in Funds &amp; Equipment. The sheet works out Armor for head, torso, arms and legs from everything worn, and Toughness shows the torso value, like 7 (2). By default the highest piece on each location counts; the Layered armor setting makes pieces add together instead. Cyberware armor and items that say they stack always add. Extra (under Armor options) is added on top. The Armor box under Vigor lists only what you are wearing, with a Take off button.',
 '<b>Minimum Strength:</b> weapons have a Min Str column that fills itself in from the gear text. Strength below it is −1 per die type on the attack, and worn armor does the same to Agility rolls (turn this off in Combat options).',
 '<b>Ammo:</b> under each ranged weapon, type the magazine size and the weapon loads. Attacks use up rounds (autofire uses 5, 10, 20, 40 or 50 by Rate of Fire), the box turns amber when low and red when empty, and Reload fills it and uses one spare magazine (leave spare empty for unlimited).',
 '<b>Loadouts:</b> save your current weapons, worn armor, vehicle and packed gear as a named set and equip it again in one click.',
 '<b>Vehicles and packed gear:</b> a character who owns a vehicle gets a Vehicles box with its stats, a wound counter (each wound is −1), a Wrecked box, a Handling number and a driving roll (Driving, Boating or Piloting). Mark one vehicle In use. Tick the gear you are carrying under Packed gear.',
 '<b>Drones:</b> on a rigger\'s sheet, + Add drone makes a drone sheet from a drone in your gear, any catalog drone, or a blank one. The drone has its own Toughness, armor, wounds, weapons and gear. Fighting, Shooting and weapon attacks use the rigger\'s Piloting dice, and other skills use the rigger\'s skill of the same name, unless you switch the drone to its own dice. It also has Jumped in (a bonus to its rolls), damaged systems and a Send out / Recall status. Use Give to... in Funds &amp; Equipment to move gear between rigger and drone. Drones have no Bennies, Edges or Power Points and are Extras unless you raise the wound limit. Tick side bar to list it under its rigger. Hiding the rigger\'s sheet hides the drones too.',
 '<b>Finds and Funds:</b> a nuyen ledger and a list of items found. Log Funds with a minus for spending, optionally say who holds them, and you get the party balance (money not assigned to a character), each character\'s own balance, and a running balance for each account. Log Items with who has them.'
 ]);
 add('dice','🎲','Dice and combat','Rolling, damage, and running a fight.',[
 '<b>Dice Roller:</b> Tools, Dice Roller is Rolling in the Shadows, a Savage Worlds style roller. Trait rolls use a trait die plus an optional Wild Die with aces, target numbers and raises. Damage rolls take any mix of dice with aces. With Post to Discord ticked, each roll goes to the dice rolls Discord channel under your display name (the GM sets that channel in GM Tools, Discord Channels). It is one switch: the same box appears on the character sheet, the quick-roll bar and the Dice Roller, and ticking it in one place changes all of them. It stays as you left it, including after you reload. Every roll in the table log and the Table stats is recorded under your character\'s name (the pinned sheet, or your sheet if you have only one), and only people without a character sheet show up under their handle.',
 '<b>Rolls everyone can see:</b> every roll from the Dice Roller or a sheet goes into the shared table roll log (even if Discord auto-post is off). The newest roll shows in the top bar (click it to open the Dice Roller; the small clear button hides it until someone rolls again; you can turn it off in Display). <b>🎲 Rolls</b> in the top bar opens the full history from any page: filter by everyone, just you, or crits and fumbles, search it, and click a roll to copy it. <b>Table Stats</b> shows streaks, glitches, raises, biggest hits and more.',
 '<b>Critical failure d4:</b> when both dice show 1, a pop-up asks if you want to roll a d4. <b>Roll d4</b> shows the result and what it means. <b>Cancel</b> skips it. The result goes in the table roll log. The GM can turn this off and decide what each number means.',
 '<b>Effects:</b> a critical failure glitches your screen with an ICE insult, and 3 or more Raises set off a legendary burst. Turn both off in Display.',
 '<b>Benny reroll and Soak:</b> under each roll, Benny reroll spends a Benny and keeps the better result (Elan adds +2). Soak spends a Benny and removes wounds. Extra Effort and Holy/Unholy Warrior buttons appear under power and Soak rolls.',
 '<b>Combat options:</b> the button under the roll box holds stances (Wild Attack, Defend, Aim, Running, Joker, Off-hand, Unstable platform, Improvised weapon), edges that ignore penalties (Marksman, Calculating) and damage add-ons. Type a target Toughness there and each Damage roll says Shaken or how many wounds.',
 '<b>Multiple actions:</b> the actions box next to Combat options: set it to 2, 3 or 4 and every trait roll gets −2 for each action after the first. Soak and Bleeding out are not affected. It resets when the turn moves on in Initiative, or set it back to 1. Frenzy, Sweep, Two-Fisted and Two-Gun Kid attacks count as one action.',
 '<b>Special attacks:</b> the Special button in the Weapons list appears when you have Frenzy, Sweep, Two-Fisted, Two-Gun Kid or Rapid Fire (or the weapon has Rate of Fire 2 or more). Pick the attack, optionally type your targets\' numbers (like 5, 6), and it rolls every die with your sheet bonuses. The Wild Die replaces your lowest die if it is higher. Check the Rate of Fire and Recoil boxes if your table plays it differently.',
 '<b>Taking damage:</b> the TAKE DAMAGE box compares damage (and the attack\'s AP) to Toughness and adds Shaken, wounds and Incapacitated for you. Soak rolls Vigor and Undo last reverses a mistake. A weapon\'s Damage button fills the box in.',
 '<b>Range &amp; Cover:</b> the 🎯 button by the sheet\'s modifier box (or Tools, Range &amp; Cover) adds up range, cover, light, aiming and called-shot modifiers. Use on my sheet roll puts the total in the modifier box.',
 '<b>Initiative:</b> Tools, Initiative is a combat tracker everyone can run: add characters and NPCs, Start combat, then Next for each turn. Use Hold, Out, Go now and Edit for special cases. The current turn shows in the top bar with who is up next. Edit sets how many cards a character is dealt (Level Headed, Quick) and + Card draws an extra card or a reroll. Cards show side by side and the highest is used by default: click another card to use it, or hover and press ✕ to discard. The ▲ ▼ arrows reorder the list, and Reset to card order undoes that. The Player name field adds players who are not on the site, and Remember keeps them under Saved players. Drag the grip on the right edge of the page to make the tracker wider on a big screen (double-click it to put it back).',
 '<b>Tabletop:</b> Tools, Tabletop (between Initiative and Dice Roller) is a shared battle map. The GM shows a map to the table; the scene effects are switched off on this page so the map keeps its own look. Press <b>＋</b> to put your character on the map (your sheet picture becomes your token), then drag tokens to move them: they snap to the grid. Everyone can move everything the GM has not locked. Drag the empty map to pan, scroll or pinch to zoom, <b>📏</b> measures a distance, and <b>📍</b> (or double-click empty ground) pings a spot so everyone sees a pulse with your name. Other players see a move within a few seconds. Parts of the map that are still black are fog the GM has not revealed yet. Tokens show a red number when that character has wounds, and the token whose turn it is in the Initiative tracker glows. Arrow keys nudge the selected token one square. The <b>panel to the right of the map</b> lists every token (click a name to jump to it) and shows what you can do with the selected one. To see more of the map, drag the grip on the right edge to make the whole Tabletop wider (it can use all the free space on a big screen), drag the bar under the map to make it taller, drag the divider beside the panel to make the panel wider or narrower, press <b>Match map shape</b> to fit the area to the picture, or use <b>Full window</b> (Esc leaves it). The <b>Grid lines</b> slider fades the grid so you can see the map itself; it only changes your own screen. Right-click drag, middle-click drag or holding Space pans the map in any tool. <b>✏️ Draw shapes</b> (or the Draw shapes section in the panel) lets everyone mark the map: <b>Rectangle</b> (corner to corner), <b>Circle</b> and <b>Ring</b> (drag out from the centre; a ring has an adjustable thickness), <b>Cone</b> (drag out from its point; it turns in 15° steps) and <b>Emanation</b> (press on a token and drag outward to spread an area from its edge; it follows the token). Pick a colour first. Each shape shows its size using the map scale. <b>🧽 Eraser</b> removes a shape when you click it, or use the ✕ beside it in the list or <b>Erase mine</b>. You can erase only your own shapes (the GM can erase any), and there is always an Undo. To change a shape that is already on the map, use the Move tool (✋): click a shape to select it (Shift-click adds more), drag it to move it, and drag the yellow handle to resize it. The Draw shapes panel has <b>Snap to grid</b> (new shapes snap to squares when it is on, and go exactly where you drag when it is off; hold Alt while drawing to flip it once, or press G), a Snap checkbox for each selected shape, a Label box (for example Fireball), Lock, Copy, Cut and Duplicate. Keyboard shortcuts work for shapes and tokens: Ctrl+Z undo, Ctrl+Y redo, Ctrl+C copy, Ctrl+X cut, Ctrl+V paste (shapes land at the pointer), Ctrl+D duplicate, Delete, arrow keys to nudge, Ctrl+A to select all shapes, and V, M, P, E and 1 to 5 to switch tools. Only the GM can copy, cut, paste or duplicate tokens; players can undo moves of their own token. <b>Combat on the table:</b> when a fight is running, a bar in the top left of the map shows the round and whose turn it is, with Back and Next buttons, and your view moves to each new turn (switch that off with <b>Move my view to each new turn</b> in the Combat section of the panel). Select a character and press <b>In tracker</b> to jump to its card. <b>Several tokens at once:</b> hold Shift and click tokens, hold Shift and drag a box around them, or use the <b>⬚ Select</b> tool; then drag any one of them to move the whole group, use the arrow keys to nudge the group, and press Ctrl+Shift+A to select every token. <b>Status markers:</b> with tokens selected, click an icon (prone, stunned, burning, bleeding and more) in the Selected token section to put it on them, and click it again to take it off. <b>Aura:</b> pick a size and a colour to draw a ring around a token that follows it everywhere. <b>Shared ruler:</b> everyone sees your measuring line while you drag the ruler, and for a few seconds afterwards. Ctrl+Z also undoes fog painting. When the GM uses <b>Look here</b>, your view moves to the spot they chose, and the GM can pin notes to the map and show them to you. <b>Health bars:</b> select a token and use the Health box: set a maximum, then press -5, -1, +1, +5 or Full (or type the number). The bar sits at the bottom of the token. You can always change the health of your own character, and the GM chooses whether players see the bar of an enemy. Every change has an Undo. <b>🎲 Roll:</b> select your token and press Roll to roll a trait or a damage roll for it. The result floats over the token for everyone, goes into the Dice Roller log and can be posted to Discord. <b>🏷 Markers (key K):</b> pick an icon, type an optional label such as checking the door, then click a square. The marker fades after about 25 seconds and you have one at a time. <b>Longer measuring:</b> with the ruler, hold Shift and press again to continue from where you stopped; select a token, set its Speed and press <b>Show range</b> to shade every square it can reach. Switch on <b>Route around walls</b> in the Measure and move section and the ruler follows the shortest way around walls and closed doors. <b>Token menu:</b> right-click a token (or press and hold on a touch screen) for Edit, Open sheet, Roll, Hide or Show, Down, Pin to the Clue Board and Remove. The <b>⌖</b> button by the zoom controls centres the map on your character. Health bars grow and show their numbers when the map is zoomed out. The <b>🕵 Clue note</b> button on a selected token pins it to the Clue Board (press it again to open that note), and a map note the GM links to the Clue Board has an <b>Open on the Clue Board</b> button.',
 '<b>Range, templates and attacks on the Tabletop:</b> pick a token that has weapons and press 📏: the ruler now says <b>Short, Medium, Long or Extreme</b> for that weapon with the attack penalty (0, −2, −4, −8). Pick the weapon in the panel, and press <b>◎ Range rings</b> to draw the rings around the token. The GM can switch the ranges between grid squares and map units. In <b>✏️ Draw shapes</b>, the <b>Templates</b> buttons drop a Small, Medium or Large blast, a Cone or a Stream; select a shape to see who it catches (they get a pink outline), and <b>🎲 Scatter</b> moves a blast after a missed throw. To attack, press <b>⚔</b>, click your own token, then click the target: a window works out the distance, range, cover and light, rolls the attack with your sheet and rolls the damage. If the hit is yours to apply it goes straight onto the target; if not, the GM sees it in a <b>Hits waiting</b> box and presses Apply. Autofire, ammo, Bennies and Soak are covered in the next item.',
 '<b>Combat on the Tabletop: autofire, Bennies, Soak and Shaken:</b> in the attack window a weapon with a Rate of Fire above 1 (or the Rapid Fire edge) shows a <b>Rate of Fire</b> box: pick how many dice to shoot. Every die is its own shot with its own damage, the recoil penalty of −2 is added (tick <b>Ignore recoil</b> for Rock and Roll when you did not move), and the first hit Shakes the target while the next ones wound it. If your sheet tracks the magazine, the rounds come off the weapon (ROF 2 uses 5, ROF 3 uses 10) and a <b>Reload</b> button fills it from a spare magazine. <b>Benny reroll</b> under the attack and <b>Benny: roll damage again</b> under the damage spend one of your Bennies and keep the better result. After a hit is applied, <b>Soak</b> spends a Benny and rolls Vigor to take wounds back. The token panel shows your Bennies (+ and −), a <b>Soak</b> button when you are wounded and a <b>Recover from Shaken</b> button when you are Shaken. When the Initiative tracker reaches a Shaken character, the player gets a box to roll Spirit or spend a Benny. Tokens without a sheet use their stat block and can carry their own Benny count; the GM can also spend from the GM pool.',
 '<b>Enemy archetypes on the Tabletop:</b> GM only. In <b>＋ Add token</b> the <b>Archetypes</b> tab lists ready-made opponents (Ganger, Halloweener, Corp security, SWAT, Yakuza, Street samurai, Mage, Rigger, Troll bouncer, drones and more). Choose how many, then click one: the tokens land on the map numbered, with Parry, Toughness, armor, weapons and health already filled in. Extras have one health level (any wound takes them out) and Wild Cards have four. Select one to see its stat block (only you see it) and press <b>Edit stat block</b> to change any number or weapon. <b>Save</b> on the token keeps the stat block in your library. The attack window fills itself from these numbers, so an attack on a Ganger only needs the dice. Press the <b>🖼</b> button on an archetype to choose a picture: it is saved for everyone and every new token of that type uses it (✕ goes back to the emoji). You can also change a placed token\'s picture in Edit and tick <b>Remember this picture</b>.',
 '<b>Drones, vehicles and chases on the Tabletop:</b> in <b>＋ Add token</b> you can put your own drones and your own vehicles on the map (the GM can add anyone). A drone token has a 🤖 and a dotted line to its rigger. A vehicle token comes from the vehicle in your Gear: select it to see its stats, press − and + for damage (four damage wrecks it), tick <b>Wrecked</b>, or press <b>🎲 Roll Driving</b> to roll with its Handling and damage. The damage is the same one shown on your sheet. Shots at a vehicle use its Toughness from the Gear entry. For a chase the GM opens the <b>🏁 Chase</b> section, selects the tokens (leader first) and presses Start: everyone sees the order and the gap between each one and the one ahead (Close, Short, Medium, Long, Extreme), also drawn as a line on the map. The GM moves the gaps and presses Next round.',
 '<b>Conditions:</b> toggle Shaken, Stunned and more on a sheet or in the tracker. Rolls from a sheet include them automatically: Distracted, Stunned, Entangled and Bound are −2 to trait rolls, Prone −2 to attacks, Blinded −6 to attacks (untick Conditions in the roll options to ignore them). Under Conditions, Liquid Courage, Terminally Ill, Habit and Weakness have switches, and Jack-of-all-Trades has a Study a skill button.',
 '<b>Scene bar:</b> the 📍 chip in the top bar shows where the party is (location, time, weather and a note), set by the GM. It links to the district\'s card.'
 ]);
 add('world','🌆','World, party and journal','Shared places, plans and your own notes.',[
 '<b>Party Management boards:</b> Plot Hooks and Missions, Downtime Activities, Finds and Funds and the Job Board each open on cards, with a Discussion button for the thread (and ← Cards to come back). Use + Add, and Edit or Delete on any entry.',
 '<b>Job Board:</b> each job has the NPC it is from (pick an NPC handle or type a name), pay, risk (Low to Deadly), deadline and status (Open, Taken, Done, Failed). Filter by status, risk or who it is from. Open jobs come first, then by deadline. A job can also name a <b>faction</b> behind it, what <b>Done</b> and <b>Failed</b> do to that faction\'s standing, and a rival faction affected. The card then shows how that faction feels about you and how they will treat you. When the job is marked Done or Failed, the GM gets a one-click <b>Apply</b> to change the standing (or Skip).',
 '<b>Downtime Activities:</b> a type (Training, Crafting, Research, Recovery, Legwork, Side job, Other), a status (Planned, In progress, Done, Cancelled), time spent, cost and result. Tick who it is for, or type extra names.',
 '<b>Plot Hooks and Missions:</b> each has a kind, a status (Lead, Active, On hold, Completed, Dead end) and a next step, so the party can see what is still live.',
 '<b>Calendar:</b> Tools, Calendar is the in-game calendar. Click + on a day to add an event, and click an event to edit or delete it. Job Board deadlines (⏰) appear automatically, and the highlighted day is the current Net Time.',
 '<b>Clocks and alarm:</b> the <b>⏱ Clocks</b> page (under Campaign) shows the countdown clocks the GM runs: a round dial split into segments that fills up as the story moves. A red or orange clock is bad when it fills and a blue one is good. The chip in the top bar says how many are running and your Home page shows them too. When a run goes loud the GM can raise the <b>alarm level</b> (Suspicious, Alert, Lockdown): the level and place show in the top bar and the screen edges glow. Now and then the GM shows a <b>street event</b>, a banner for something happening around you. Recent ones are listed at the bottom of the Clocks page. Only the GM can change clocks and the alarm.',
 '<b>Clue Board:</b> World Building, Clue Board is a shared pin-and-string board for the whole party. <b>+ Clue</b>, <b>+ Person</b>, <b>+ Place</b>, <b>+ Job</b> and <b>+ Note</b> pin up a note. <b>Add existing</b> pins a job, mission, contact, NPC, map pin, district or character that already exists, and the note links back to its page. Drag a note to move it and drag the empty background to pan. Click a note, then <b>Connect</b> and click a second note to tie them together with red string. Click the dot on a string to name it (works for, seen at, paid by) or cut it. Double-click a note to edit it. The zoom buttons, <b>Fit all</b> and the find box help on a big board. Hover over a note to read its full title and what we know without opening Edit (click a note to see it in the bar above the board on a touch screen). To use more of your screen, drag the grip on the right edge to make the board wider, drag the bar under the board to make it taller or press <b>Full window</b> (Esc leaves it); <b>Reset size</b> goes back. <b>📄 Summary</b> writes out everything on the board as text, grouped by kind with the connections of each note, so you can copy it or save it as a .txt file. Everyone can add, move and connect. Removing a note has an Undo, and new notes show as New for everyone else. To pick several notes, hold Shift and click them, or hold Shift and drag a box on the background (or press <b>⬚ Select</b> and drag); drag any one to move them all. Ctrl+Z and Ctrl+Y (or the ↶ and ↷ buttons) undo and redo, Ctrl+C, Ctrl+X, Ctrl+V and Ctrl+D copy, cut, paste and duplicate notes together with the strings between them, Ctrl+A selects everything, Delete removes the selection and the arrow keys nudge it. <b>Groups:</b> <b>▭ Group</b> draws a labelled box (select notes first and it wraps them). Drag the title bar to move the box together with every note inside it, drag the corner to resize it and press ✎ or double-click the title to rename, recolour or delete it. <b>String kinds:</b> click the dot on a string and pick Ally, Enemy, Suspected or Confirmed to change its colour and style. <b>Tags:</b> select notes and press Unverified, Verified, Red herring, Resolved or Urgent under the board. The Show only buttons then fade or hide the other notes (choose which with the next button), and Hide resolved tidies the board. <b>Pictures and dates:</b> Edit lets you add a picture (a small thumbnail shows on the note, a large one when you hover, and double-clicking it opens the full picture) and an in-game date. <b>🗓 Timeline</b> lists the notes in date order; change a date right there, or click a note to find it on the board. <b>GM only:</b> the GM can hide a note from the players with <b>Hide from players</b> and reveal it later; it shows as New when revealed. <b>Map links:</b> <b>Link to map</b> adds a button that opens the Tabletop at a spot or token. <b>Print board</b> opens the print window (choose Save as PDF there) with a picture of the board and every note, and <b>Save picture</b> downloads the whole board as a PNG.',
 '<b>Seattle Map:</b> drag to pan and scroll or pinch to zoom. <b>Add pin</b>, then click the map to drop a pin with a title, kind, security level and notes. A pin can link to a job, contact, mission, NPC or board. Use the filters and Find box to narrow pins. Pins can be edited, moved and deleted. A pin with an in-game date and time appears on the Calendar with a 📍 (and View on calendar / Show on map jump between the two). On a big screen, drag the grip on the right edge of the page to make the map wider, and the bar under the map to make it taller. Double-click either one to put it back.',
 '<b>Seattle Districts:</b> World Building, Seattle Districts lists every district with its security rating (AAA down to Z), who runs it, places of note and rumors. The first picture shows on the district\'s card and all of them show in a gallery you can click to enlarge. Search the list, and click a district for its card.',
 '<b>Newspaper:</b> the front page published after each session, in in-game order. Click Read to open an edition, or Publish a new edition (title, in-game date and a PDF). The person who added an edition, or the GM, can remove it.',
 '<b>Matrix News:</b> stories anyone can post (form at the bottom of the page) plus an automated wire of background headlines (not facts). You can delete your own stories and the GM can delete any.',
 '<b>Handout Vault:</b> maps, documents, images and any other file up to 25 MB. Images and PDFs open on the page and everything else downloads.',
 '<b>My Notes (private):</b> your own notebook for each session. + New note takes a title, session name or number, session date, optional in-game date, tags and formatted notes. Sort, filter by session or tag, and search the text of all your notes. Deleted notes come back with Show deleted notes, and Download saves everything as a file. Only you can see your notes: other players cannot, the GM cannot read them on the board, and they are left out of the GM\'s backup.',
 '<b>Feedback &amp; Suggestions:</b> open to everyone. + Add feedback to post a suggestion, bug report, question or praise. Anyone can edit items, change their status (New, Seen, Planned, Done, Not planned), and filter the list.'
 ]);
 add('display','🎨','Display, alerts and accessibility','Everything here only affects you.',[
 '<b>Display (⚙ Menu):</b> ambient theme, accent color, scanlines, compact layout, the headline ticker, the latest-roll chip, mention pop-ups, critical roll effects, rare glitch effects, sound effects, glossary underlines, link previews and whether Home opens first when you arrive. Press Apply to save.',
 '<b>Text size:</b> Small to Huge, and it changes all text on the site. <b>High contrast</b> gives pure black and white, bright accents, no glow, thicker outlines and no atmosphere effects.',
 '<b>Scene atmosphere:</b> when the GM sets the scene, the background follows it (district picture, mood from the security rating, weather, day or night). Set it to Full, Subtle or Off. It switches itself off if your device asks for reduced motion.',
 '<b>Sound effects:</b> a chime on new posts and a double chime when you are mentioned. Off by default.',
 '<b>Muted boards:</b> Display lists the boards you have muted, with an Unmute button.',
 '<b>Discord pings:</b> add your Discord user ID in Profile and the Discord channel pings you when you are @mentioned or sent a private message.',
 '<b>Broadcasts:</b> the GM can send a message that pops up on everyone\'s screen (news flash, trid alert, security alert, corp memo or Matrix notice). Click Got it to close it. Anyone who opens the site within a few hours still sees it once.',
 '<b>Theme extras:</b> Ambient theme changes the colors just for you. Rain adds falling rain.'
 ]);
 add('tips','🛟','If something looks wrong','Quick fixes.',[
 '<b>Working on it:</b> if a save or action is slow, a message at the bottom of the screen says it is working, and the button you pressed stays locked until it finishes. Please wait instead of clicking again. Your action has not been lost.',
 '<b>It failed to post:</b> refresh and try again. Your draft is kept.',
 '<b>The page looks out of date:</b> force a refresh with Ctrl+Shift+R (Cmd+Shift+R on a Mac).',
 '<b>You deleted something by mistake:</b> use the Undo bar right away, or restore it from the Trash. Things deleted from the Tabletop, the Clue Board and the other pages can be put back by the GM from the Recycle bin for 30 days.',
 '<b>Your text is kept:</b> if you were typing in a pop-up form (a Clue Board note, a job, a note) and the page reloaded or closed by accident, open the same form again and your text is put back. Closing the form yourself clears it.',
 '<b>You cannot sign in:</b> ask the GM to add your email to the allow list.',
 '<b>Etiquette:</b> stay in character on public boards and keep real-life chat in Discord.'
 ]);
 if(typeof hqOn==='function'&&hqOn())add('safehouse','🏠','Team safe house','A shared base for the team.',[
 '<b>Safe House:</b> Game Management, Safe House shows where the team\'s base is, its security level, rent, upgrades and a shared stash of gear and loot. <b>Pay rent</b> logs the payment in Finds and Funds. <b>Put something in</b> moves an item from your character into the stash and <b>Take</b> moves it back. Recent activity lists who did what.'
 ]);
 add('gm','🛠','For the GM','Only the GM sees this section.',[
 '<b>Dashboard:</b> who is online, the last backup, recently changed sheets, open jobs, active plot hooks and new feedback in one place.',
 '<b>Party at a Glance:</b> Game Management, Party at a Glance is a live table of every runner\'s wounds, Toughness, Parry, bennies, Strain, Heat and conditions. − and + change wounds or bennies without opening the sheet, and clicking a name opens that sheet. Your own and NPC sheets are left out unless you tick Include my own sheets.',
 '<b>Set the scene:</b> click the scene chip in the top bar to set the location, time, weather and an optional note. Pick time, weather and mood from lists and save the setup as a preset to reuse. You can choose Matrix, Astral or Red alert, pick or upload a backdrop picture, turn the atmosphere off for a scene, and tick Also show on character sheets and the dice roller. The <b>Backdrop gallery</b> in the same window has 20 built-in pictures (neon city, rain alley, corporate lobby, docks, tunnels, club, night market and more). Click one to use it, or choose <b>Match the place</b> and the site picks a picture from the location, weather and time. Your own upload and the district pictures still work. To hide, rename or swap any of these pictures, or add your own, use <b>GM Hub, Backdrops</b>.',
 '<b>Alarm level:</b> click the alarm chip in the top bar (🚨 Alarm: Quiet) and pick Quiet, Suspicious, Alert or Lockdown. Add a place and a note if you like. Everyone sees the level in the top bar and in the scrolling banner, the screen edges tint and pulse faster as it climbs, and a banner announces every change. <b>Stand down</b> goes back to Quiet. <b>End the run</b> shows the highest level reached, suggests Heat (Alert +1, Lockdown +2), lets you choose who was on the run, then resets the alarm. Everything has an Undo.',
 '<b>Countdown clocks:</b> on the Clocks page press <b>+ New clock</b>, or start from a template such as Security response arrives or Hack in progress. Pick how many segments (3 to 12) and whether it is a danger, progress or plain timer clock. Click a segment or press +1 to fill it, and − to back off. A clock can carry a secret line that only you see until it fills, and it can be hidden from the players altogether. Finished clocks move to the bottom and deleted ones go to the Recycle bin.',
 '<b>Street events:</b> GM Hub, Street events (or the 🎲 Event chip in the top bar) rolls on a table of ready-made events in ten kinds: law, gangs, corporate, Matrix, magic, weather and city, street life, opportunities, hazards and strange things. Choose the kind, how bad it should be and the area (it follows the security rating of the scene district unless you change it). Every result has a line for everyone and a <b>GM only</b> hook. <b>Show to the table</b> sends the line as a banner, a ticker headline and a short screen effect such as flickering lights or a siren glow, and it is listed on the Clocks page. <b>Edit first</b> lets you reword it for one use. Open <b>The whole table</b> to switch events off or add your own.',
 '<b>Backdrop library:</b> GM Hub, Backdrops shows every scene picture. <b>Hide</b> one to keep it out of the Set the scene lists and out of ✨ Match the place (you can show it again any time). <b>Edit</b> a picture to change its name, its <b>words</b> (the place, weather and time words that ✨ Match the place looks for) or to use your own picture in its place; <b>Back to the original</b> or <b>Reset everything</b> brings the built-in one back. <b>+ Add pictures</b> uploads up to 8 of your own at a time, then Edit each to give it words. A picture you delete goes to the Recycle bin for 30 days. Everyone sees your replacement pictures behind the scene.',
 '<b>Ask players to do something:</b> your own Home page has a GM section. <b>Ask players to do something</b> sends a request to everyone or to chosen players, with an optional due note and a button that takes them to the right page. Players see it on their Home page (and a number beside the link), tick it off, and you see who has. Close or delete a request when you are done with it.',
 '<b>Heat, Rep and factions:</b> you change Heat, Street Rep and faction standing on Heat and Rep, with a history of who, when and why. Open <b>each runner</b> under a faction to move one character above or below the party standing (their personal standing is the party number plus the change; reset puts them back). Jobs that name a faction and are marked Done or Failed show up under <b>Faction changes waiting</b> on both the Job Board and Heat and Rep, with Apply (and Undo) or Skip. You can add a player who has no sheet with + Player without a sheet. Give factions profiles, including a GM Secret box that is never shown to players. Add districts one by one or the standard 12 with one button, and attach pictures with Add pictures.',
 '<b>Running the Tabletop:</b> on the Tabletop page, <b>⬆ Add map</b> uploads a picture (large ones are shrunk for you), then <b>FIT THE GRID</b> opens: press <b>Draw one square</b> and drag a box over any one square on the map, then fine tune with the numbers and nudge buttons and <b>Save grid</b>. <b>＋</b> adds tokens: Characters (from sheets), NPCs and contacts (with their pictures), <b>Encounter</b> (quick enemies such as "Ganger" ×4 that are marked temporary), props and items, and your saved Library. Select a token for Edit, Copy, Down, Lock, Hide from players, Save to library and Remove, or double-click it to edit. <b>Clear encounter</b> removes every temporary token at once (with Undo). <b>🌫 Fog</b> hides the map from the players until you drag to reveal squares with a brush or box; you see hidden areas dimmed, and players cannot see tokens standing in fog (their own characters always show). Use <b>Map settings</b> for the distance scale, grid color and fog, and the map picker to prepare other maps privately and then <b>Show players this map</b>. Hiding is on screen only, like hidden sheets. Everything lives in the <b>panel beside the map</b>: the token list (with quick Hide, Down and Remove buttons), the Fog options (Reveal or Hide, Brush or Box, brush sizes, Reveal all, Hide all, and a Fog on/off switch; press <b>Paint fog</b> and drag on empty ground, while you can still move tokens and pan with right-click or Space), and <b>Grid and scale</b>. If the squares do not suit a picture, change <b>Square size</b> with the slider, the Smaller and Bigger buttons or the number boxes, nudge the grid, and press <b>Save grid</b>. The <b>Fog, as you see it</b> slider only changes how dark hidden areas look to you; players always see black. <b>GM extras:</b> <b>🔭 Look here</b> (key L) moves the view of every player to the spot you click, and <b>📡 Send my view</b> in the GM tools section moves them to what you are looking at, zoom included. <b>📌 Add note</b> (key N) pins a note to the map; only you see it until you press the eye to show it to the players, and you can open, move the view to, or delete it from the list. Select one or more tokens and press <b>Reveal</b> (key R) to uncover the fog within the number of squares you choose, or <b>Cover</b> to hide it again. Every fog change, whether painted or revealed around a token, can be undone with Ctrl+Z. As with hidden sheets and tokens, a hidden note is hidden on screen only. <b>Walls, doors and sight:</b> press <b>🧱</b> (key W) or open GM tools and notes. <b>Wall</b> and <b>Door</b> draw along the grid lines from corner to corner, <b>Room</b> draws four walls at once and <b>Remove</b> deletes the one you click. With the Move tool, click a door to open or close it and Shift-click to lock it. Give a token a <b>Sight or light</b> size in the Selected token section; while fog of war is on, it uncovers the fog around the token as it moves, and walls and closed doors block it. Put a lamp prop with a light size anywhere to light a room. <b>Auto-reveal</b> switches this off for a map, and players see only the doors they have uncovered. <b>Saved views:</b> in Views, layers and files, <b>Save this view</b> bookmarks where you are looking; <b>Go</b> jumps there and the 📡 button brings every player there too, even on another map. <b>Layers:</b> <b>Add a picture</b> puts a floor plan, handout or overlay on top of the map; it stays hidden from players until you press the eye. Drag it to move it, drag the yellow corner to resize it and use the Opacity slider. <b>Export this map</b> saves everything on the map (picture, grid, fog, tokens, walls, notes, layers, views and shapes) to one file, and <b>Import a map file</b> loads it back as a new map, in this campaign or another. Hidden walls and layers are hidden on screen only. A map note can be linked to a Clue Board note from its edit window.',
 '<b>Broadcast:</b> Game Management, GM Broadcast, or the button on the Dashboard, sends a pop-up to everyone.',
 '<b>ICE event:</b> GM Tools, ICE Event fires a red alert banner, flicker and scrambled post text for a few seconds. Use it when the decker trips a trace.',
 '<b>Critical Failure d4:</b> GM Tools, Critical Failure d4 turns the pop-up on or off and lets you write what each number from 1 to 4 means (or leave a line empty to show only the number).',
 '<b>Discord channels:</b> GM Tools, Discord Channels: paste a webhook address next to each board and everything posted there appears in the matching Discord channel in full under the poster\'s handle. Off Screen Scenes and Private Channels work best with a Discord Forum channel, where each scene or conversation becomes its own forum post. Scene messages show as Character (Player). Private messages are only copied if you connect that row, and players are told when it is on. Dossiers are never sent. The first row, <b>Dice rolls</b>, is the channel for rolls posted with Post to Discord; it has a Test button like the others, and if it is empty rolls go to the older dice channel or the main channel as before.',
 '<b>Discord summary:</b> GM Tools, Discord Summary builds a digest of what happened since the last one. Edit it, then post it.',
 '<b>Ticker and weather:</b> GM Tools lets you add scrolling banner lines (written like SHADOWTALK: your text) and your own places, weather, roads and traffic for the Seattle chip. They mix in with the built-in ones, and a setting controls how often yours show. Use Preview to see a sample. Headlines at the top can be edited with the pencil button.',
 '<b>GM Hub:</b> the GM Hub in the left menu holds the GM pages as tabs: Dashboard, Party, Heat &amp; Rep, Broadcast, Recycle bin, Storage and Tools. <b>Recycle bin:</b> everything deleted from the Tabletop, Clue Board, sheets, gear, handouts, calendar and more waits here. Restore puts it back, Delete forever removes it, and anything older than 30 days is removed for you. <b>Storage:</b> shows how much space pictures, files, the database and backups use, and lists uploaded pictures that nothing uses any more so you can delete them.',
 '<b>Backup and restore:</b> ⚙ Menu, Backup downloads everything as one file (private notes and uploaded images are not inside it). Restore from backup lets you pick a nightly backup, see what is missing, in the trash or different now, and put back only the items you tick. Export everything in GM Tools does the same download. The roll scoreboard under Table Stats has a Reset button, and the table roll log has Clear.',
 '<b>Undo for the GM:</b> after a Heat or Rep change, a scene change, a broadcast, clearing the roll log, resetting the scoreboard or making an NPC, an Undo button appears at the bottom of the screen for a few seconds.',
 '<b>Safe house:</b> GM Tools, Team Safe House: set up the base (location, rent, security, upgrades), then press Show it to the players. Until you do, nobody else can see it or anything about it. You can hide it again at any time and nothing is deleted.'
 ],{gm:1});
 return S}
function helpHtml(){const S=HELP_S().filter(s=>!s.gm||isOwner);
 const toc=S.map(s=>`<button type="button" class="btn sm" data-hj="${s.id}">${s.ico} ${esc(s.title)}</button>`).join(' ');
 const secs=S.map((s,i)=>`<details class="hsec" id="hs-${s.id}" ${i===0?'open':''}><summary>${s.ico} ${esc(s.title)}</summary><p class="hint">${s.intro}</p><ul>${s.items.map(x=>`<li>${x}</li>`).join('')}</ul></details>`).join('');
 return `<div class="help" id="helproot"><h2>How to use RSS</h2><p><button class="btn sm" id="wnb">What's new</button> <button class="btn sm" id="hopen">Open all</button> <button class="btn sm" id="hclose">Close all</button></p>
 <input id="hsq" placeholder="Search this Help page..." autocomplete="off" style="max-width:420px;margin:6px 0 8px"><div class="hint" id="hsn" style="margin:0 0 6px"></div>
 <div class="hjump">${toc}</div>${secs}</div>`}
function helpShow(){$('#view').innerHTML=helpHtml();const R=$('#helproot'),all=()=>[...R.querySelectorAll('details.hsec')];
 const wb=$('#wnb');if(wb)wb.onclick=showNews;
 $('#hopen').onclick=()=>all().forEach(d=>d.open=true);$('#hclose').onclick=()=>all().forEach(d=>d.open=false);
 R.querySelectorAll('[data-hj]').forEach(b=>b.onclick=()=>{const d=$('#hs-'+b.dataset.hj);if(!d)return;if(d.hidden)return;d.open=true;d.scrollIntoView({block:'start',behavior:'smooth'})});
 const q=$('#hsq');q.oninput=()=>{const w=q.value.toLowerCase().split(/\s+/).filter(Boolean);let n=0;
  all().forEach(d=>{let any=0;d.querySelectorAll('li').forEach(li=>{const hit=!w.length||w.every(x=>li.textContent.toLowerCase().includes(x));li.hidden=!hit;if(hit)any++});
   const t=!w.length||any>0||d.querySelector('summary').textContent.toLowerCase().includes(w.join(' '));d.hidden=!t;if(w.length&&any)d.open=true;n+=any});
  R.querySelectorAll('[data-hj]').forEach(b=>{const d=$('#hs-'+b.dataset.hj);b.style.display=d&&d.hidden?'none':''});
  $('#hsn').textContent=w.length?(n?n+' match'+(n==1?'':'es')+'.':'Nothing found. Try a shorter word.'):''}}
{const st=document.createElement('style');st.textContent=`.help details.hsec{border:1px solid var(--line);background:var(--panel);margin:0 0 8px}
.help details.hsec>summary{cursor:pointer;padding:9px 12px;font-weight:700;color:var(--cy);font-size:16px;list-style:none}
.help details.hsec>summary::-webkit-details-marker{display:none}.help details.hsec>summary::before{content:"▸ ";color:var(--mg)}.help details.hsec[open]>summary::before{content:"▾ "}
.help details.hsec>.hint{margin:0 12px 6px}.help details.hsec>ul{margin:0 12px 10px 12px;padding-left:18px}.help details.hsec li{margin:0 0 7px;line-height:1.45}
.help .hjump{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 12px}`;document.head.appendChild(st)}
/* Help for the page you are on: just the matching topics, in a small window */
const HELP_PAGE={__tbl:['Tabletop','Range, templates and attacks','Combat on the Tabletop','Enemy archetypes on the Tabletop','Drones, vehicles and chases','Running the Tabletop'],__clues:['Clue Board'],__init:['Initiative','Conditions'],__dice:['Dice Roller','Rolls everyone can see','Critical failure d4','Dice in a post'],
 __sheets:['Creating a sheet','What is on it','Who can edit','Edges and hindrances','Advances','Favorite rolls','Play mode','Layout','History and printing','Duplicate'],__shop:['Gear & Shopping','Custom gear','Loadouts'],
 __cal:['Calendar'],__map:['Seattle Map'],__dist:['Seattle Districts'],__vault:['Handout Vault'],__notes:['My Notes (private)'],__paper:['Newspaper'],__news:['Matrix News'],__tl:['Timeline'],__dir:['Portraits and the directory'],__npc:['NPC Handles'],
 __heat:['Heat and Rep','Heat, Rep and factions'],__clk:['Clocks and alarm','Alarm level','Countdown clocks'],__evt:['Street events'],__art:['Backdrop library'],__gmd:['Dashboard'],__party:['Party at a Glance'],__bc:['Broadcast'],__bin:['You deleted something by mistake','Recycle bin'],__stor:['Storage'],__gm:['Set the scene','Ticker and weather','Backup and restore','Undo for the GM','Discord channels','Discord summary'],
 __inbox:['Inbox','Mention alerts'],__unread:['Unread tracking'],__saved:['Saved posts'],__trash:['You deleted something by mistake'],__safe:['Safe House'],__home:['Home','The top bar'],__fb:['Feedback & Suggestions'],__emo:['Emoji'],__dos:['GM Dossiers'],__gloss:['Rules and slang'],__help:['The top bar'],
 _:['New post','Order','Mute a board','Reactions','Mentions','Unread tracking']};
const hpDec=s=>String(s).replace(/&amp;/g,'&').replace(/\\'/g,"'");
function helpPageItems(b){const want=(HELP_PAGE[b]||HELP_PAGE._).map(hpDec),out=[];HELP_S().filter(s=>!s.gm||isOwner).forEach(s=>s.items.forEach(x=>{const m=String(x).match(/^<b>([^<]*)<\/b>/);if(!m)return;const lead=hpDec(m[1]).replace(/:\s*$/,'').trim();if(want.some(w=>lead.toLowerCase()===w.toLowerCase()||lead.toLowerCase().startsWith(w.toLowerCase())))out.push(x)}));return out}
function helpPageOpen(){const nm=(()=>{const r=NAV_REG&&NAV_REG[board];if(r)return qsPlain(r.inner).replace(/^\S+\s+/u,m=>/[A-Za-z0-9\/]/.test(m)?m:'');const h=HUB_TABS.find(t=>t[0]===board);return h?h[2]:((allBoards().find(b=>b.id===board)||{}).name||'This page')})();
 const L=helpPageItems(board);$('#modal').innerHTML=`<div class="modal"><div class="box" style="max-width:640px"><h2>❓ HELP: ${esc(nm.toUpperCase())}</h2>${L.length?`<ul class="hpl">${L.map(x=>`<li>${x}</li>`).join('')}</ul>`:'<div class="hint">There is no short help for this page. Open the full Help page to read about everything.</div>'}<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="hpfull">Open the full Help page</button><button class="btn" id="hpsh">⌨ Keyboard shortcuts</button><button class="btn grn" id="cx">Close</button></div></div></div>`;
 $('#cx').onclick=closeM;$('#hpfull').onclick=()=>{closeM();board='__help';thread=null;query='';render()};$('#hpsh').onclick=()=>{closeM();shOpen()}}
document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('#helpQ'))helpPageOpen()});
